# Sensitive Medical Symptoms that require doctor referral
MEDICAL_REFUSAL_TRIGGERS = [
    "chest pain", "heart attack", "pregnant", "pregnancy", "cancer", "hiv", "hepatitis",
    "fever today", "covid symptoms", "breathing trouble", "severe headache", "taking antibiotics",
    "seizure", "unconscious", "dizziness now"
]

import urllib.request
import json
from app.config import settings

def call_groq_llm(user_msg: str, lang: str = "en") -> str:
    """Calls Groq OpenAI-compatible chat completion endpoint using openai/gpt-oss-20b"""
    if not settings.LLM_API_KEY or settings.LLM_PROVIDER != "groq":
        return None

    system_prompt = (
        "You are BloodBuddy, the official AI awareness assistant for BloodLink (Chhattisgarh Emergency Blood Coordination Network).\n"
        "Your mission is to educate the public on voluntary blood and platelet donation, dispel fears, explain donor eligibility, preparation, and recovery.\n"
        f"Respond in the requested language ('{lang}'). If 'hi', reply in clean Hindi. If 'hinglish', reply in conversational Hinglish. Otherwise English.\n"
        "Safety instructions:\n"
        "- Do not diagnose medical conditions or prescribe medications.\n"
        "- If the user mentions acute symptoms (chest pain, active fever, etc.), tell them to consult a qualified physician immediately.\n"
        "- Keep answers helpful, warm, and concise (under 200 words)."
    )

    url = f"{settings.LLM_BASE_URL.rstrip('/')}/chat/completions"
    headers = {
        "Authorization": f"Bearer {settings.LLM_API_KEY}",
        "Content-Type": "application/json",
        "User-Agent": "BloodLink/1.0"
    }


    payload = json.dumps({
        "model": settings.LLM_MODEL,
        "messages": [
            {"role": "system", "content": system_prompt},
            {"role": "user", "content": user_msg}
        ],
        "temperature": 0.4,
        "max_tokens": 400
    }).encode("utf-8")

    req = urllib.request.Request(url, data=payload, headers=headers)
    try:
        with urllib.request.urlopen(req, timeout=12) as resp:
            data = json.loads(resp.read().decode("utf-8"))
            content = data["choices"][0]["message"]["content"].strip()
            return content
    except Exception as e:
        print(f"[-] Groq LLM call notice: {e}. Utilizing verified clinical FAQ fallback.")
        return None

def get_bloodbuddy_response(user_msg: str, lang: str = "en") -> Dict:
    query = user_msg.lower().strip()

    # Medical diagnosis / triage refusal check
    for trigger in MEDICAL_REFUSAL_TRIGGERS:
        if trigger in query:
            return {
                "answer": "⚠️ Medical Safety Notice: BloodBuddy is an educational assistant and cannot diagnose conditions, prescribe treatments, or certify individual clinical suitability. If you are experiencing symptoms, medical conditions, or are on medication, please consult a qualified physician or blood bank medical officer directly before donating.",
                "language": lang,
                "is_medical_refusal": True,
                "citations": [
                    {"title": "WHO Clinical Guidelines on Transfusion Safety", "publisher": "World Health Organization", "url": "https://www.who.int/"}
                ],
                "suggestions": [
                    "What are the general donor eligibility criteria?",
                    "How does the donation process work?",
                    "Find a nearby donation camp"
                ]
            }

    # 1. Try Groq AI Provider first
    llm_answer = call_groq_llm(user_msg, lang)
    if llm_answer:
        return {
            "answer": llm_answer,
            "language": lang,
            "is_medical_refusal": False,
            "citations": [
                {"title": "National Blood Transfusion Guidelines", "publisher": "Ministry of Health & Family Welfare", "url": "https://eraktkosh.mohfw.gov.in/"},
                {"title": "WHO Transfusion Safety", "publisher": "World Health Organization", "url": "https://www.who.int/"}
            ],
            "suggestions": [
                "Does blood donation cause weakness?",
                "Can I donate after getting a tattoo?",
                "How often can I donate blood?"
            ]
        }

    # 2. Keyword matching against reviewed FAQs fallback
    best_match = None
    max_score = 0
    for faq in FAQS:
        score = sum(1 for kw in faq["keywords"] if kw in query)
        if score > max_score:
            max_score = score
            best_match = faq

    if best_match and max_score > 0:
        if lang == "hi":
            answer = best_match["answer_hi"]
        elif lang == "hinglish":
            answer = best_match["answer_hinglish"]
        else:
            answer = best_match["answer_en"]

        return {
            "answer": answer,
            "language": lang,
            "is_medical_refusal": False,
            "citations": best_match["citations"],
            "suggestions": [
                "Does blood donation cause weakness?",
                "Can I donate after getting a tattoo?",
                "How often can I donate blood?"
            ]
        }

    # Default fallback
    if lang == "hi":
        ans = "नमस्ते! मैं BloodBuddy हूँ। आप मुझसे रक्तदान के फायदे, नियम, पात्रता और भ्रांतियों के बारे में पूछ सकते हैं। कृपया व्यक्तिगत चिकित्सीय सलाह के लिए डॉक्टर से संपर्क करें।"
    elif lang == "hinglish":
        ans = "Hello! Main BloodBuddy hoon, BloodLink ka educational assistant. Aap mujhse donation guidelines, recovery time, tattoo deferral aur donor myths ke baare mein pooch sakte hain."
    else:
        ans = "Hello! I am BloodBuddy, BloodLink's awareness assistant. I can answer questions about donor eligibility, donation procedures, myths, and recovery. For personal clinical diagnosis, please consult a healthcare professional."


    return {
        "answer": ans,
        "language": lang,
        "is_medical_refusal": False,
        "citations": [
            {"title": "National Blood Transfusion Guidelines", "publisher": "Ministry of Health & Family Welfare", "url": "https://eraktkosh.mohfw.gov.in/"}
        ],
        "suggestions": [
            "Does donating blood hurt?",
            "How much blood is collected in one visit?",
            "Who is eligible to donate blood?"
        ]
    }
